<script setup>
import InputError from '@/Components/InputError.vue'; import SeoHead from '@/Components/Public/SeoHead.vue'; import PublicLayout from '@/Layouts/PublicLayout.vue'; import { useForm } from '@inertiajs/vue3'; const props=defineProps({products:Array,selectedProductId:{type:String,default:''}}); const form=useForm({name:'',organization:'',email:'',phone:'',location:'',organization_type:'',product_id:props.selectedProductId,number_of_users:'',preferred_demo_date:'',preferred_demo_time:'',message:'',source:'Website'}); const submit=()=>form.post(route('demo.store'),{preserveScroll:true,onSuccess:()=>form.reset()});
</script>
<template><SeoHead title="Request a Software Demo | KernelBridge" description="Request a tailored demonstration of KernelBridge software for your organisation." canonical="https://kernelbridge.com/demo"/><PublicLayout><section class="page-hero"><div class="page-shell"><p class="section-label !text-teal-300">Request a demo</p><h1 class="page-title">See the right workflows for your organisation.</h1><p class="page-intro">Tell us about your operation and preferred schedule. Our sales team will prepare a focused walkthrough.</p></div></section><section class="page-shell grid gap-12 py-20 lg:grid-cols-[.8fr_1.2fr]"><div><h2 class="section-title">What to expect</h2><ul class="mt-7 space-y-5 text-slate-600"><li>✓ A short discovery conversation</li><li>✓ A walkthrough focused on your use case</li><li>✓ Clear implementation and next-step guidance</li></ul></div><form class="form-card" @submit.prevent="submit"><div v-if="$page.props.flash.success" role="status" class="success-message">{{ $page.props.flash.success }}</div><div class="form-grid"><label>Your name<input v-model="form.name" required autocomplete="name"/><InputError :message="form.errors.name"/></label><label>Organization<input v-model="form.organization" required autocomplete="organization"/><InputError :message="form.errors.organization"/></label><label>Work email<input v-model="form.email" required type="email" autocomplete="email"/><InputError :message="form.errors.email"/></label><label>Phone<input v-model="form.phone" type="tel" autocomplete="tel"/><InputError :message="form.errors.phone"/></label><label>Location<input v-model="form.location" autocomplete="address-level2" placeholder="City, State or Country"/><InputError :message="form.errors.location"/></label><label>Organization type<select v-model="form.organization_type" required><option value="">Select type</option><option value="school">School</option><option value="university">University</option><option value="healthcare">Healthcare</option><option value="business">Business</option><option value="hospitality">Hospitality</option><option value="government">Government</option><option value="nonprofit">Nonprofit</option><option value="other">Other</option></select><InputError :message="form.errors.organization_type"/></label><label>Product<select v-model="form.product_id"><option value="">Help me choose</option><option v-for="product in products" :key="product.id" :value="product.public_id">{{ product.name }} — {{ product.industry }}</option></select><InputError :message="form.errors.product_id"/></label><label>Number of users<input v-model="form.number_of_users" type="number" min="1" placeholder="Estimated users"/><InputError :message="form.errors.number_of_users"/></label><label>Preferred demo date<input v-model="form.preferred_demo_date" type="date"/><InputError :message="form.errors.preferred_demo_date"/></label><label>Preferred demo time<input v-model="form.preferred_demo_time" type="time"/><InputError :message="form.errors.preferred_demo_time"/></label></div><label>What would you like to improve?<textarea v-model="form.message" rows="5"/><InputError :message="form.errors.message"/></label><button class="form-button" :disabled="form.processing">{{ form.processing?'Submitting…':'Request demo' }}</button></form></section></PublicLayout></template>
